package de.meiapps.meicraft;
import java.util.*;
import java.io.*;
public final class MechanicsTests {
 static int checks;static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 static void rejected(Runnable work){boolean failed=false;try{work.run();}catch(IllegalArgumentException expected){failed=true;}check(failed,"invalid movement rejected");}
 public static void main(String[] args)throws Exception{
  for(int dir=0;dir<6;dir++)for(int distance=1;distance<=4;distance++){
   World w=NatureTests.flat(false);w.x=60;w.z=60;int[] d=Mechanics.DIRECTIONS[dir];Mechanics.Block button=new Mechanics.Block(15,10,15,14);w.set(15,10,15,14);List<Mechanics.Block> blocks=List.of(new Mechanics.Block(20,15,20,7),new Mechanics.Block(20,16,20,8));for(Mechanics.Block b:blocks)w.set(b.x,b.y,b.z,b.type);
   Mechanics.Link link=new Mechanics.Link(button,blocks,dir,distance,false);w.mechanics.install(w,link);byte[] before=w.blocks.clone();int[] inventory=w.progress.inventory.clone();w.mechanics.apply(w,link);
   check(w.get(20+d[0]*distance,15+d[1]*distance,20+d[2]*distance)==7,"first block moves in every direction");check(w.get(20+d[0]*distance,16+d[1]*distance,20+d[2]*distance)==8,"second material retained, including overlapping translations");
   World loaded=World.decode(w.encode());Mechanics.Link saved=loaded.mechanics.links.get(loaded.idx(15,10,15));check(saved!=null&&saved.moved&&saved.encode().equals(link.toggle().encode()),"switch definition and position survive save");loaded.mechanics.apply(loaded,saved);check(Arrays.equals(before,loaded.blocks),"return reconstructs exact original world");check(Arrays.equals(inventory,loaded.progress.inventory),"no inventory creation or loss");
   check(Mechanics.decode(link.encode()).encode().equals(link.encode()),"canonical marker roundtrip");
  }
  World w=NatureTests.flat(false);w.x=60;w.z=60;w.set(10,10,10,14);w.set(20,10,20,7);Mechanics.Link link=new Mechanics.Link(new Mechanics.Block(10,10,10,14),List.of(new Mechanics.Block(20,10,20,7)),0,3,false);w.mechanics.install(w,link);
  w.set(22,10,20,3);byte[] before=w.blocks.clone();rejected(()->w.mechanics.apply(w,link));check(Arrays.equals(before,w.blocks)&&!w.mechanics.links.get(w.idx(10,10,10)).moved,"obstacle along swept path rejects entire operation");w.set(22,10,20,0);w.x=22.5f;w.y=11.6f;w.z=20.5f;rejected(()->w.mechanics.apply(w,link));w.x=60;w.z=60;
  w.mechanics.apply(w,link);w.set(20,10,20,3);before=w.blocks.clone();rejected(()->w.mechanics.apply(w,link.toggle()));check(Arrays.equals(before,w.blocks),"obstructed return also preserves every block");
  rejected(()->new Mechanics.Link(link.button,List.of(link.button),0,1,false));rejected(()->new Mechanics.Link(link.button,link.blocks,0,5,false));rejected(()->new Mechanics.Link(link.button,List.of(new Mechanics.Block(20,10,20,10)),0,1,false));
  w.set(10,10,10,0);check(w.mechanics.links.isEmpty(),"mining a switch removes its local connection");
  for(String bad:List.of("mech_!",link.encode()+"A","mech_"+"a".repeat(101))){boolean failed=false;try{Mechanics.decode(bad);}catch(IOException expected){failed=true;}check(failed,"invalid metadata rejected");}
  World namedWorld=NatureTests.flat(false);namedWorld.set(10,10,10,14);namedWorld.set(20,10,20,7);namedWorld.x=21.5f;namedWorld.y=11.6f;namedWorld.z=20.5f;
  Mechanics.Link named=new Mechanics.Link(new Mechanics.Block(10,10,10,14),List.of(new Mechanics.Block(20,10,20,7)),0,1,false,"Geheimtür");
  namedWorld.mechanics.install(namedWorld,named);check(namedWorld.mechanics.links.size()==1,"configuration is allowed while the builder stands in the path");rejected(()->namedWorld.mechanics.apply(namedWorld,named));
  check(Mechanics.decode(named.encode()).name.equals("Geheimtür")&&Mechanics.decode(named.toggle().encode()).name.equals("Geheimtür"),"shared name survives roundtrip and toggle");
  check(World.decode(namedWorld.encode()).mechanics.links.values().iterator().next().name.equals("Geheimtür"),"name survives offline save and load");
  List<Mechanics.Block> nine=new ArrayList<>();for(int i=0;i<9;i++)nine.add(new Mechanics.Block(20,10+i,20,7));Mechanics.Link longest=new Mechanics.Link(named.button,nine,0,1,false,"ÄÄÄÄÄÄÄÄÄÄ");check(longest.encode().matches("mech_[A-Za-z0-9_-]{20,116}"),"longest named nine-block marker fits existing database rules");check(Mechanics.decode(longest.encode()).name.equals(longest.name),"bounded unicode name is canonical");
  rejected(()->new Mechanics.Link(named.button,nine,0,1,false,"Ä".repeat(11)));
  World door=NatureTests.flat(false);door.x=60;door.z=60;door.set(10,10,10,14);List<Mechanics.Block> panel=new ArrayList<>();for(int y=0;y<3;y++)for(int z=0;z<3;z++){Mechanics.Block b=new Mechanics.Block(20,10+y,20+z,7);panel.add(b);door.set(b.x,b.y,b.z,b.type);}Mechanics.Link gate=new Mechanics.Link(named.button,panel,0,1,false,"3x3 Tür");door.mechanics.install(door,gate);byte[] original=door.blocks.clone();door.mechanics.apply(door,gate);for(Mechanics.Block b:panel)check(door.get(b.x+1,b.y,b.z)==7&&door.get(b.x,b.y,b.z)==0,"each cell of a 3x3 door moves");door.mechanics.apply(door,gate.toggle());check(Arrays.equals(original,door.blocks),"3x3 door returns without loss");List<Mechanics.Block> ten=new ArrayList<>(panel);ten.add(new Mechanics.Block(20,14,20,7));rejected(()->new Mechanics.Link(named.button,ten,0,1,false));
  Mechanics.Block second=new Mechanics.Block(12,10,10,14),third=new Mechanics.Block(14,10,10,7);Mechanics.Link pressure=gate.mode(true).withButtons(List.of(gate.button,second,third)).named("ÄÄÄÄÄÄÄÄÄÄ");
  check(pressure.encode().matches("mech_[A-Za-z0-9_-]{20,140}"),"largest nine-block, three-switch pressure marker fits bounded wire format");Mechanics.Link decoded=Mechanics.decode(pressure.encode());check(decoded.pressure&&decoded.buttons.size()==3&&decoded.state(true).pressure&&decoded.named("Tor").buttons.size()==3,"pressure mode and all controls survive codec, toggling and renaming");
  door.set(12,10,10,14);door.set(14,10,10,7);door.mechanics.links.clear();door.mechanics.install(door,pressure);World reopened=World.decode(door.encode());check(reopened.mechanics.at(reopened,12,10,10).pressure&&reopened.mechanics.at(reopened,14,10,10)!=null,"all three controls find the same persisted mechanism");
  check(Mechanics.pressed(pressure,Mechanics.space(door),12.5f,12.6f,10.5f),"standing on the second plate activates the group");check(!Mechanics.pressed(pressure,Mechanics.space(door),12.5f,13.6f,10.5f),"jumping above a plate is not standing on it");check(!Mechanics.pressed(pressure,Mechanics.space(door),13f,12.6f,10.5f),"plate boundary does not activate its neighbor");
  rejected(()->pressure.withButtons(List.of(pressure.button,second,third,new Mechanics.Block(15,10,10,14))));rejected(()->pressure.withButtons(List.of(pressure.button,new Mechanics.Block(80,10,10,14))));rejected(()->pressure.withButtons(List.of(pressure.button,panel.get(0))));
  Mechanics.Link timed=pressure.delayed(5);check(timed.encode().matches("mech_[A-Za-z0-9_-]{20,140}")&&Mechanics.decode(timed.encode()).closeDelay==5,"longest delayed multi-control metadata fits existing 1.2.0 bound");check(timed.named("Tor").toggle().withButtons(timed.buttons).mode(false).closeDelay==5,"timer survives renaming, motion and control/mode changes");
  door.mechanics.links.put(door.idx(timed.button.x,timed.button.y,timed.button.z),timed);check(World.decode(door.encode()).mechanics.links.values().iterator().next().closeDelay==5,"closing delay survives offline save/load");rejected(()->pressure.delayed(3));
  Mechanics.PressureTimer timer=new Mechanics.PressureTimer();Mechanics.Link delayed=pressure.delayed(2).state(true);check(timer.desired(delayed,false,10000),"two-second return starts held open");check(timer.desired(delayed,false,11999),"return waits for the complete delay");check(!timer.desired(delayed,false,12000),"return becomes due at two seconds");check(timer.desired(delayed,true,12500),"a player on any plate cancels the previous countdown");check(timer.desired(delayed,false,14000)&&timer.desired(delayed,false,15999)&&!timer.desired(delayed,false,16000),"last player leaving starts a fresh full countdown");
  check(!timer.desired(delayed.state(false),false,17000),"elapsed timers never reopen an empty closed door");check(timer.desired(delayed.delayed(5),false,20000)&&timer.desired(delayed.delayed(5),false,24999)&&!timer.desired(delayed.delayed(5),false,25000),"five-second setting uses its full duration");check(!timer.desired(delayed.delayed(0),false,26000),"zero preserves immediate closing");check(new Mechanics.PressureTimer().desired(delayed,false,30000),"rejoin conservatively waits the full configured delay");
  System.out.println("PASS: "+checks+" reversible mechanics, collision, inventory and persistence checks");
 }
}
